import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter overall student marks (0 - 100): ");
        int marks = scanner.nextInt();

        // Defensive boundary check:
        if (marks < 0 || marks > 100) {
            System.out.println("Error: Marks must be between 0 and 100.");
        } else if (marks >= 90) {
            System.out.println("Grade: A+ (Dean's Honours List)");
        } else if (marks >= 80) {
            System.out.println("Grade: A (Distinction)");
        } else if (marks >= 70) {
            System.out.println("Grade: B (First Class)");
        } else if (marks >= 60) {
            System.out.println("Grade: C (Second Class)");
        } else if (marks >= 50) {
            System.out.println("Grade: D (Pass)");
        } else {
            System.out.println("Grade: F (Fail - Remediate)");
        }

        System.out.println("Academic evaluation completed.");
        scanner.close();
    }
}

