import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int age = scanner.nextInt();
        String cat;
        if (age < 13) cat = "Child";
        else if (age < 20) cat = "Teen";
        else if (age < 60) cat = "Adult";
        else cat = "Senior";
        System.out.println("Category: " + cat);
        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
